function parseOptionalNumber(raw,label){
  const s=String(raw??"").trim();if(!s)return{value:null,error:null};
  const n=Number(s);if(!Number.isFinite(n)||n<0)return{value:null,error:label+"格式错误"};return{value:n,error:null};
}

function parseHeaderTable(text,keyHeaders){
  const raw=String(text||"").replace(/\r\n?/g,"\n").replace(/^\uFEFF/,"");
  // 中文：优先按 Tab 分列，否则允许中英文逗号在一张表内混合，保留双引号内分隔符。
  // English: Prefer Tab where present; otherwise accept mixed Chinese/ASCII commas outside quoted cells.
  const first=raw.split("\n")[0]||"";
  const tabDelimited=first.includes("\t");
  // 中文：报价含“备注”列时，中文逗号及分号是正文而不是分隔符，避免条款被拆成多行。
  // English: Preserve Chinese punctuation and semicolons in quotation remark columns.
  const hasRemarkColumn=/物料备注|报价备注|备注/.test(first);
  const records=[];let row=[],field="",inside=false;
  for(let i=0;i<raw.length;i++){
    const ch=raw[i];
    if(ch==='"'){
      if(inside&&raw[i+1]==='"'){field+='"';i++;}else inside=!inside;
    }else if(!inside&&(tabDelimited?ch==="\t":ch===","||(!hasRemarkColumn&&ch==="，"))){row.push(field.trim());field="";}
    else if(!inside&&(ch==="\n"||(!hasRemarkColumn&&(ch==="；"||ch===";")))){
      row.push(field.trim());field="";
      if(row.some(v=>v!==""))records.push(row);
      row=[];
    }else field+=ch;
  }
  if(inside)return{headers:[],rows:[],errors:["CSV 双引号未闭合"],warnings:[]};
  row.push(field.trim());if(row.some(v=>v!==""))records.push(row);
  if(!records.length)return{headers:[],rows:[],errors:["第一行必须是表头"],warnings:[]};
  const headers=records[0],errors=[],warnings=[];
  const duplicate=headers.filter((h,i)=>h&&headers.indexOf(h)!==i);
  if(duplicate.length)errors.push("重复列标题："+[...new Set(duplicate)].join("、"));
  if(headers.some(h=>!h))errors.push("表头存在空列名");
  if(!keyHeaders.some(k=>headers.includes(k)))errors.push("缺少必需主键标题："+keyHeaders.join(" 或 "));
  const rows=records.slice(1).map((cells,i)=>{
    // 中文：允许省略尾部可选单元格，主键和数量/单位等必填值由各业务解析器校验。
    // English: Pad missing trailing cells; business parsers still validate required keys and values.
    if(cells.length>headers.length)errors.push("第 "+(i+2)+" 行数据列数 "+cells.length+" 超过表头 "+headers.length+"，请检查是否错位");
    const data={};headers.forEach((h,j)=>data[h]=cells[j]??"");
    return{data,rowNo:i+2};
  });
  return{headers,rows,errors,warnings};
}
function findHeaderValue(row,headers){
  for(const h of headers){if(Object.prototype.hasOwnProperty.call(row,h))return row[h]}
  return"";
}

function parseQuoteRows(text){
  const table=parseHeaderTable(text,["RFQ Line ID","存货编码","物料编码"]);
  if(table.errors.length){const rows=[];rows._headerErrors=table.errors;return rows}
  const result=table.rows.map(({data,rowNo})=>{
    const line=String(data["RFQ Line ID"]||"").trim(),
      code=String(findHeaderValue(data,["存货编码","物料编码"])||"").trim(),
      price=findHeaderValue(data,["报价单价","单价","阶梯价","价格","报价"]),
      lead=findHeaderValue(data,["交期","交期天数"]),
      moq=findHeaderValue(data,["MOQ","最小起订量"]),
      rawStatus=findHeaderValue(data,["报价状态","状态"]),
       remark=findHeaderValue(data,["物料备注","报价备注","备注"]);
    const status=rawStatus|| (price?"quoted":"review"),errors=[];
    if(!line&&!code)errors.push("第 "+rowNo+" 行缺少报价行身份");
    if(line&&code){
      const obj=items.find(it=>it.lineId===line);
      if(obj&&obj.id!==code)errors.push("第 "+rowNo+" 行 RFQ Line ID 与存货编码不匹配");
    }
    return{itemRef:line||code,price,lead,moq,status,remark,_rowNo:rowNo,_errors:errors};
  });
  result._headers=table.headers;return result;
}
function normalizeQuoteStatus(v){
  const s=String(v||"quoted").trim().toLowerCase();
  if(["未报价","noquote","no quote"].includes(s))return"noquote";
  if(["不供货","不能供货","cannot","cannot supply"].includes(s))return"cannot";
  if(["quoted","报价","正常报价"].includes(s))return"quoted";
  if(["review","待检查"].includes(s))return"review";
  return null;
}

function parseTierPrice(raw){
  const s=String(raw??"").trim(),errors=[];
  if(!s)return{price:null,tiers:[],errors:["价格不能为空"]};
  if(!s.includes(":")){const n=Number(s);return Number.isFinite(n)&&n>=0?{price:n,tiers:[],errors:[]}:{price:null,tiers:[],errors:["单价格式错误"]}}
  const tiers=[];
  s.split(/[|｜]/).map(x=>x.trim()).filter(Boolean).forEach(part=>{
    const pos=part.lastIndexOf(":");if(pos<=0){errors.push("阶梯格式错误："+part);return}
    const range=part.slice(0,pos).trim(),priceRaw=part.slice(pos+1).trim(),price=Number(priceRaw);
    if(!Number.isFinite(price)||price<0){errors.push("阶梯价格错误："+part);return}
    let min,max=null;
    if(/^\d+(?:\.\d+)?\+$/.test(range))min=Number(range.slice(0,-1));
    else if(/^\d+(?:\.\d+)?-\d+(?:\.\d+)?$/.test(range)){const p=range.split("-").map(Number);min=p[0];max=p[1]}
    else {errors.push("阶梯区间错误："+range);return}
    if(!(min>0)||max!==null&&max<min){errors.push("阶梯区间反向或非法："+range);return}
    tiers.push({min,max,price});
  });
  tiers.sort((a,b)=>a.min-b.min);
  for(let i=1;i<tiers.length;i++){const prev=tiers[i-1],cur=tiers[i];if(prev.max===null||cur.min<=prev.max)errors.push("阶梯区间重叠")}
  return{price:null,tiers,errors};
}

function effectivePriceForLine(line,qty){
  if(!line||line.status!=="quoted")return null;
  if(!line.tiers?.length)return line.price==null||!Number.isFinite(Number(line.price))?null:Number(line.price);
  const q=Number(qty);if(!Number.isFinite(q)||q<=0)return null;
  const hit=line.tiers.find(t=>q>=t.min&&(t.max==null||q<=t.max));
  return hit?Number(hit.price):null;
}

function validateQuotePreview(rows){
  // 中文：防止采购员先打开报价页、后又增加供应商分配，而第一轮尚无报价时错误显示“多报”。
  // English: Refresh empty first-round draft scope even if the buyer revisited assignments after opening quotation import.
  ensureFirstRound();
