  resolved.forEach(r=>{const key=r.item?.lineId||r.itemRef;seen.set(key,(seen.get(key)||0)+1)});
  return resolved.map(r=>{
    const status=normalizeQuoteStatus(r.status),lineId=r.item?.lineId||r.itemRef,itemId=r.item?.id||"",duplicate=(seen.get(lineId)||0)>1,codeMatches=items.filter(x=>x.id===String(r.itemRef||"").trim()).length,ambiguous=!r.item&&codeMatches>1,errors=[];if(!status)errors.push("报价状态无法识别");if(status==="review")errors.push("价格和状态均为空，请核对");if(r._errors?.length)errors.push(...r._errors);if(typeof (r.remark??"")!=="string"||String(r.remark??"").length>2000)errors.push("物料备注超过 2000 字或不是文本");if(ambiguous)errors.push("物料编码对应多条 RFQ 行，请使用 RFQ Line ID");
    let check="已报价";
    if(status==="review")check="待检查";else if(ambiguous)check="数据错误";else if(duplicate)check="重复";else if(!r.item||!expected.has(lineId))check="多报";else if(status==="noquote")check="明确未报价";else if(status==="cannot")check="不供货";
    let parsed={price:null,tiers:[],errors:[]},lead={value:null,error:null},moq={value:null,error:null},effective=null;
    if(status==="quoted"){
      parsed=parseTierPrice(r.price);errors.push(...parsed.errors);
      lead=parseOptionalNumber(r.lead,"交期");moq=parseOptionalNumber(r.moq,"MOQ");if(lead.error)errors.push(lead.error);if(moq.error)errors.push(moq.error);
      effective=effectivePriceForLine({status,price:parsed.price,tiers:parsed.tiers},r.item?.qty);
