    return {...r,status,lineId,itemId,priceParsed:parsed,leadValue:lead.value,moqValue:moq.value,effectivePrice:effective,errors,coverageCheck:check,scopeReason};
  });
}

function planQuoteImportCommit(rows){
  const checked=validateQuotePreview(rows.map(r=>r._rawInput||r));
  const valid=[],skipped=[];
  checked.forEach((r,i)=>{
    const candidate={...r,_rawInput:rows[i]._rawInput||rows[i],_entryMethod:rows[i]._entryMethod||"import"};
    if(["已报价","明确未报价","不供货"].includes(r.coverageCheck)&&!r.errors.length)valid.push(candidate);
    else skipped.push(candidate);
  });
  return{valid,skipped,total:checked.length};
}
